"""Original acute liver failure and drug-induced liver injury questions."""
from qbank_authoring import question,ref,finalize
AL=ref('ACG 2023 Acute Liver Failure Guideline','https://doi.org/10.14309/ajg.0000000000002340')
DI=ref('AASLD Drug, Herbal and Dietary Supplement-Induced Liver Injury Guidance','https://pmc.ncbi.nlm.nih.gov/articles/PMC9936988/')
NA=ref('ACMT 2026 IV Acetylcysteine Duration Practice Statement','https://www.acmt.net/news/acmt-practice-statement-duration-of-intravenous-acetylcysteine-therapy-following-acetaminophen-overdose-2026-update/')
rows=[]
def q(*a,**k):rows.append(question(*a,**k))

q('Which adult presentation meets the usual acute liver failure definition?', 'Acute liver injury with INR at least 1.5 and hepatic encephalopathy within 26 weeks, without pre-existing cirrhosis',[
 ('ALT 2,000 U/L with normal INR and normal mentation','This is substantial injury but does not establish ALF.'),('Chronic cirrhosis with recurrent ascites for five years','This is chronic decompensated disease rather than the usual ALF definition.'),('Isolated indirect bilirubin 3 mg/dL with normal enzymes','This does not meet the injury, coagulopathy or encephalopathy criteria.')],
 'Organ dysfunction, not enzyme magnitude alone, defines the syndrome', '**Coagulopathy and encephalopathy distinguish ALF from acute liver injury without failure.**', ['The usual time limit is 26 weeks.','Selected etiologies can have prior unrecognized disease, so the clinical interpretation requires expertise.'], '**Escalate early to an experienced liver/transplant center.**', ['Cause-specific investigation and stabilization proceed together.','Do not wait for deep coma or a very high bilirubin before referral.'], [['Acute injury alone','No mandatory encephalopathy'],['ALF','Acute dysfunction plus INR/HE criteria'],['Chronic cirrhosis with deterioration','Different ACLF framework']], [AL])
q('A patient with newly recognized ALF has grade I encephalopathy and rising INR. What is the best referral strategy?', 'Early discussion and transfer planning with a transplant-capable liver center',[
 ('Wait until grade IV coma before referral','Later transfer is more hazardous and can lose options.'),('Use the ALT peak as the sole referral threshold','ALT does not adequately measure functional failure.'),('Refer only if the cause remains unknown after a week','Known causes can still require transplantation and intensive expertise.')],
 'Preserve the window for safe escalation', '**ALF can deteriorate over hours and requires specialized neurological, metabolic and transplant assessment.**', ['Prognostic scoring assists but does not replace serial clinical judgment.','Transport should anticipate airway and hemodynamic risk.'], '**Treat while arranging transfer.**', ['Correct hypoglycemia, address suspected toxins and monitor organ function.','Avoid unnecessary procedures or sedatives that complicate neurological assessment.'], [['Early encephalopathy','Already a referral signal'],['Cause-specific therapy','Begin promptly'],['Transfer','Before advanced instability when possible']], [AL], 'clinical_scenario')
q('Which situation is appropriate for applying a standard Rumack–Matthew acetaminophen nomogram?', 'A single acute ingestion with a reliable known time and a serum level obtained at least four hours afterward',[
 ('Repeated supratherapeutic dosing over several days','The standard nomogram is not validated for that exposure pattern.'),('An unknown ingestion time with established liver failure','The nomogram cannot safely exclude toxicity in this context.'),('A one-hour level used as definitive exclusion of later toxicity','The standard treatment plot requires the appropriate later sampling time.')],
 'A risk tool is only valid for its intended exposure model', '**The nomogram links concentration to elapsed time after a single known-time ingestion.**', ['The commonly used US treatment line begins at 150 micrograms/mL at four hours.','Modified-release products, coingestants and delayed absorption may require additional sampling/protocol steps.'], '**Do not withhold NAC in a high-risk non-nomogram situation.**', ['Use toxicology guidance, enzymes and the clinical exposure assessment.','A delayed presentation can have a low drug level despite severe injury.'], [['Single known-time overdose','Nomogram applicable'],['Staggered/unknown-time exposure','Different assessment'],['Early pre-four-hour sample','Not definitive exclusion']], [AL,DI])
q('A patient has suspected acetaminophen-related ALF two days after ingestion, but the serum drug concentration is now undetectable. What is the appropriate treatment principle?', 'Give NAC when acetaminophen toxicity remains a plausible cause; a late negative concentration does not exclude it',[
 ('Withhold NAC because the serum assay must remain positive throughout liver injury','The drug can clear before injury peaks.'),('Use the nomogram at an invented ingestion time','This creates a false risk estimate.'),('Treat only if bilirubin exceeds 20 mg/dL','Acetaminophen injury can have relatively low bilirubin with massive hepatocellular damage.')],
 'Toxic metabolite injury can outlast measurable parent drug', '**NAC can benefit established acetaminophen injury even after circulating drug is eliminated.**', ['History may be incomplete in encephalopathy or unintentional overdose.','Very high aminotransferases with relatively low bilirubin can support the differential.'], '**Use poison-center and liver-center support.**', ['Do not delay treatment while pursuing perfect historical certainty.','Monitor INR, glucose, lactate, kidneys and neurological status.'], [['Late drug level','Can be negative'],['Clinical suspicion','Can still justify NAC'],['ALF','Urgent specialist pathway']], [AL,NA], 'clinical_scenario')
q('After the initial IV NAC course, acetaminophen remains detectable and ALT/INR are worsening. What should happen?', 'Continue NAC and reassess serially rather than stopping solely because the scheduled infusion time has elapsed',[
 ('Stop automatically at 21 hours regardless of laboratory trajectory','The course must be extended when stopping criteria are not met.'),('Switch to observation until jaundice appears','This delays ongoing antidotal support.'),('Use normal serum sodium as the only stopping test','It does not establish resolution of acetaminophen toxicity.')],
 'A clock is not a substitute for physiological stopping criteria', '**Persistent drug, rising injury markers or poor-prognosis features warrant continued therapy.**', ['Assess coagulation, mental status and overall clinical recovery.','The 2026 ACMT statement emphasizes individualized continuation beyond a standard course when needed.'], '**Coordinate the endpoint with toxicology expertise.**', ['Continue monitoring until drug clearance and convincing improvement are established.','Transplant evaluation is not postponed because NAC is ongoing.'], [['Standard course complete','Reassess, do not stop blindly'],['Persistent toxicity','Continue'],['Clinical/laboratory recovery','Inform stopping decision']], [NA], 'clinical_scenario')
q('How does NAC primarily protect against early acetaminophen hepatotoxicity?', 'Restores glutathione capacity to detoxify the reactive metabolite NAPQI',[
 ('Blocks all gastrointestinal acetaminophen absorption days after ingestion','That is not its principal antidotal mechanism.'),('Directly replaces every necrotic hepatocyte','NAC does not act as a cell transplant.'),('Chelates hepatic copper','That is unrelated to acetaminophen detoxification.')],
 'Reactive metabolite formation becomes dangerous when detoxification is overwhelmed', '**Acetaminophen metabolism produces NAPQI, which is normally neutralized by glutathione.**', ['Large exposure can deplete protective capacity and produce covalent injury.','NAC supplies substrate/support for detoxification and has additional benefits in established failure.'], '**Start early when indicated but do not assume late use is futile.**', ['Timing affects the magnitude of benefit.','Clinical treatment decisions depend on exposure, levels and injury status.'], [['NAPQI','Reactive toxic metabolite'],['Glutathione','Detoxification pathway'],['NAC','Restores/supports protection']], [DI,AL])
q('In selected adult non-acetaminophen ALF, when is NAC benefit most supported?', 'Early encephalopathy stages, particularly grades I–II, as an adjunct while treating the cause and assessing transplant need',[
 ('Only after irreversible grade IV coma in every patient','The strongest transplant-free-survival signal is in earlier stages.'),('As a guarantee that transplantation is unnecessary','It does not guarantee recovery.'),('As a substitute for all etiological investigation','Cause-specific treatment remains important.')],
 'An adjunct can be useful without being a universal cure', '**Evidence supports selected early non-acetaminophen ALF use in adults.**', ['The conclusion should not be indiscriminately extrapolated to every age group or phenotype.','The overall management remains cause- and severity-specific.'], '**Continue rapid reassessment.**', ['A deteriorating patient still needs transplant decisions.','Do not delay treatment of HBV, HSV or another identified cause.'], [['Early adult non-APAP ALF','NAC consideration'],['Advanced failure','Benefit less assured'],['All stages','Cause treatment and transplant review']], [AL,ref('AASLD: Getting the Knack of NAC','https://www.aasld.org/liver-fellow-network/core-series/clinical-pearls/getting-knack-nac')])
q('An ALF patient progresses to grade III encephalopathy with inability to protect the airway. What is the appropriate care direction?', 'Intensive-care airway protection and neurological monitoring with transplant-center management',[
 ('Continue unmonitored oral medication while awaiting spontaneous awakening','Aspiration and cerebral complications are major risks.'),('Give sedatives without airway planning solely to simplify observation','This can obscure deterioration and compromise ventilation.'),('Delay escalation until bilirubin reaches a preset value','Neurological severity itself warrants escalation.')],
 'Advanced encephalopathy changes immediate safety needs', '**Airway protection and careful ventilatory/hemodynamic management are priorities.**', ['Avoid hypoxia and hypotension.','Cerebral edema risk requires specialist monitoring and preventive measures.'], '**Preserve diagnostic information where possible without compromising safety.**', ['Document neurological status before sedation when feasible.','Continue transplant and cause-specific treatment decisions.'], [['Grade III/IV HE','Airway and ICU assessment'],['Cerebral risk','Avoid secondary insults'],['Definitive planning','Transplant-center pathway']], [AL], 'clinical_scenario')
q('Why is routine plasma transfusion solely to normalize INR generally avoided in nonbleeding ALF?', 'It can cause volume complications and obscure a useful prognostic trend without a routine proven benefit',[
 ('ALF patients can never bleed','Bleeding and procedure-related risks still require individualized management.'),('INR is irrelevant to prognosis','Its trajectory is important in ALF.'),('A normal INR after transfusion proves hepatic recovery','Replacement factors can transiently change the number without restoring hepatocyte function.')],
 'Correct a clinical indication rather than an isolated laboratory appearance', '**Plasma may be appropriate for active bleeding or selected invasive procedures.**', ['INR does not fully capture the rebalanced hemostatic state.','Viscoelastic testing can inform selected decisions where available.'], '**Do not hide deterioration by repeatedly replacing factors without a reason.**', ['Track the native clinical and laboratory trajectory.','Balance procedural benefit against transfusion and fluid risk.'], [['No bleeding/procedure need','No routine INR normalization'],['Active bleeding','Individualized hemostatic treatment'],['Prognostic interpretation','Replacement confounds INR']], [AL])
q('An ALF patient has a generalized seizure and glucose 38 mg/dL. What is the immediate treatment priority?', 'Prompt IV glucose correction while managing airway/seizure safety and investigating the broader cause',[
 ('Wait for MRI before treating the glucose','Severe hypoglycemia is immediately dangerous and reversible.'),('Assume the seizure proves irreversible cerebral edema','Hypoglycemia is a treatable contributor.'),('Avoid all glucose because carbohydrate cannot be given in liver failure','Glucose support can be essential in ALF.')],
 'Loss of hepatic metabolic reserve can cause recurrent hypoglycemia', '**Frequent glucose monitoring is necessary because a one-time correction may not last.**', ['Reduced glycogen reserves and gluconeogenesis contribute.','Seizures can also have neurological or electrolyte causes that need assessment.'], '**Treat immediate metabolic threats while the full evaluation continues.**', ['Use an appropriate infusion strategy after rescue.','Coordinate fluids, sodium and cerebral-risk management.'], [['Low glucose','Immediate correction'],['ALF','Risk of recurrence'],['Seizure','Assess multiple reversible causes']], [AL], 'clinical_scenario')
q('A pregnant patient develops fever, very high aminotransferases and ALF with little jaundice. HSV hepatitis is suspected. What is the appropriate immediate direction?', 'Prompt IV acyclovir while diagnostic testing and specialist management proceed',[
 ('Wait for typical skin vesicles before considering treatment','HSV hepatitis can occur without classic external lesions.'),('Use oral vancomycin as the specific antiviral','It does not treat HSV.'),('Exclude HSV because bilirubin is only mildly elevated','An anicteric severe hepatitis pattern can occur.')],
 'A rare but treatable cause can deteriorate rapidly', '**Pregnancy and immunosuppression are important contexts for HSV hepatitis.**', ['Blood PCR and selected tissue assessment support diagnosis.','Delay can be harmful when suspicion is high.'], '**Treat before every diagnostic uncertainty is resolved.**', ['Adjust acyclovir for renal function as appropriate.','Maintain the ALF/transplant and obstetric pathways.'], [['HSV concern','Early acyclovir'],['Absent vesicles','Does not exclude'],['Testing','PCR and selected tissue']], [AL], 'clinical_scenario')
q('Which combination is part of the classic King’s College high-risk criteria for acetaminophen ALF when the severe acidosis pathway is not met?', 'INR above 6.5, creatinine above about 3.4 mg/dL and grade III–IV encephalopathy together',[
 ('ALT above 1,000 U/L alone','This is not that prognostic combination.'),('Bilirubin above 3 mg/dL alone','This does not establish the stated high-risk criteria.'),('A positive anti-HCV antibody alone','This is neither a severity measure nor the acetaminophen prognostic criterion.')],
 'Use a prognostic rule in its exact disease setting', '**The classic acetaminophen criteria include severe acidosis or the specified multivariable combination.**', ['The criteria have imperfect sensitivity and should not be the only referral trigger.','Lactate, trajectory and organ support needs add important clinical information.'], '**Discuss transplantation before waiting for every threshold to be crossed.**', ['Earlier center assessment is safer.','A score informs selection; it does not replace expert prognostication.'], [['APAP KCC combination','INR, creatinine and advanced HE'],['Alternative pathway','Severe acidosis'],['Limitation','Do not delay referral until met']], [AL])
q('In ALF with substantial hyperammonemia and cerebral-edema concern, which renal-support principle is often favored when renal replacement is indicated?', 'Continuous renal replacement therapy for steadier metabolic and hemodynamic control',[
 ('Rapid intermittent osmotic shifts are always preferable in cerebral-risk patients','Abrupt shifts and hypotension can be problematic.'),('Dialysis is forbidden in every ALF patient','Renal support can be important.'),('A high ammonia alone should be treated by massive protein restriction without specialist care','This is not adequate critical-care management.')],
 'Support metabolism without adding abrupt circulatory or osmotic injury', '**Continuous therapy can provide ammonia and fluid control with better hemodynamic tolerance in unstable patients.**', ['Indication and timing are individualized with critical-care and liver expertise.','Ammonia is one part of cerebral-risk assessment, not the only determinant.'], '**Treat the underlying ALF simultaneously.**', ['Avoid hypoxia, hypotension and severe sodium disturbances.','Renal support is a bridge, not a replacement for recovery or transplantation.'], [['CRRT','Steady clearance/support'],['Cerebral risk','Avoid secondary physiological insults'],['Definitive endpoint','Recovery or transplant']], [AL])
q('Which feature distinguishes intrinsic from idiosyncratic DILI?', 'Intrinsic injury is relatively predictable and dose-related, whereas idiosyncratic injury occurs unpredictably in susceptible individuals',[
 ('Idiosyncratic injury means the patient imagined symptoms','It is a genuine adverse drug reaction.'),('Intrinsic injury can never occur with acetaminophen','Acetaminophen overdose is a classic intrinsic example.'),('All idiosyncratic reactions occur within minutes of the first dose','Latency is variable and can be weeks to months or occasionally longer.')],
 'Mechanism and predictability affect the exposure assessment', '**Dose, latency, host susceptibility and drug signature all help interpret causality.**', ['Idiosyncratic reactions may be immune-mediated or involve other mechanisms.','A normal previous course does not guarantee future safety.'], '**Do not confuse an unpredictable reaction with an uninvestigable one.**', ['Construct a full medication timeline.','Exclude alternative liver diseases and assess dechallenge.'], [['Intrinsic','Dose-related/predictable'],['Idiosyncratic','Susceptibility-dependent/unpredictable'],['Assessment','Timeline plus alternatives']], [DI])
